#!/usr/bin/env python3
"""Write (--write) or verify (--check) web/src/fixtures/action-kinds.data.ts, the web tests' copy
of what ``GET /actions/kinds`` serves for the built-in kinds."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from culture_rules.model.action_kinds import describe_kinds  # noqa: E402

TARGET = ROOT / "web" / "src" / "fixtures" / "action-kinds.data.ts"
HEADER = (
    "// Generated by scripts/export-action-kinds.py from the Python catalogue; do not edit.\n"
    "// What GET /actions/kinds serves for the built-in kinds.\n"
    "export const ACTION_KINDS_DATA: unknown = "
)


def render() -> str:
    body = json.dumps({"items": describe_kinds()}, indent=2, ensure_ascii=False)
    return f"{HEADER}{body};\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    if args.write:
        TARGET.write_text(render(), encoding="utf-8")
        print(f"wrote {TARGET}")
        return 0
    if TARGET.read_text(encoding="utf-8") != render():
        print(f"{TARGET} is out of date; run: python scripts/export-action-kinds.py --write")
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
